INSERT INTO projects (id, title, project_year, description, image_url, position, published, created_at, updated_at) SELECT '30d388ce-2945-5b43-bbb7-f39dbfaae87b', 'Netra 2025', 2025, 'This H-frame quadcopter was developed for autonomous aerial scanning missions. It features a Raspberry Pi 5 for onboard image processing and a Pixhawk flight controller for stable autonomous navigation. The drone can take off, perform scans, and land autonomously within a geofenced area. Built for precision and reliability, it is ideal for mapping, inspection, and disaster assessment applications.', '/images/projects/netra-2025.jpg', 1000, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM projects WHERE title = 'Netra 2025' AND project_year = 2025);
