INSERT INTO projects (id, title, project_year, description, image_url, position, published, created_at, updated_at) SELECT '327eb455-26a6-5a2e-a316-7fbe9b034335', 'Vitrak 2025', 2025, 'This X-frame quadcopter is designed for autonomous payload delivery using GPS navigation. Equipped with a Pixhawk controller and onboard sensors, it can take off, fly to a target location, and deliver payloads with high accuracy. A Raspberry Pi module handles mission logic and communication. The system ensures fully automated operation from launch to safe return, ideal for disaster relief and logistics tasks.', '/images/projects/vitrak-2025.jpg', 1001, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM projects WHERE title = 'Vitrak 2025' AND project_year = 2025);
