INSERT INTO projects (id, title, project_year, description, image_url, position, published, created_at, updated_at) SELECT '56439589-0631-594b-8bd3-8730bbbae56b', 'Gajraj 09', 2024, 'This fixed-wing RC plane was built for a prestigious TechFest competition at IIT Bombay, where the team secured 10th rank among 250+ teams. Designed for high lift, stability, and efficient flight performance, it excelled in both endurance and payload missions. The aircraft was entirely student-designed and fabricated, showcasing innovation in aerodynamics and control. It stands as a testament to the team’s engineering excellence and dedication to aeromodelling.', '/images/projects/gajraj-09-2024.png', 1002, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM projects WHERE title = 'Gajraj 09' AND project_year = 2024);
