INSERT INTO projects (id, title, project_year, description, image_url, position, published, created_at, updated_at) SELECT 'b1dcf44f-2df3-5e9c-ab60-84b77038f4f5', 'Prayas', 2024, 'This trainer RC plane was built to teach freshers of 2024-25 the basics of aerodynamics and maneuverability. Lightweight and stable, it helps beginners understand lift, drag, and control response through hands-on flying. The project aims to build foundational skills in aeromodelling and UAV design.', '/images/projects/prayas-2024.jpg', 1004, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM projects WHERE title = 'Prayas' AND project_year = 2024);
