INSERT INTO projects (id, title, project_year, description, image_url, position, published, created_at, updated_at) SELECT 'e1df5209-53b9-5faa-a7d5-5f64a4cd0d5d', 'Abhyas', 2024, 'This RC plane was built by the team for the Wright Flight competition at TechFest NITK 2024. Designed and fabricated from scratch, it focused on aerodynamic efficiency and payload stability. The model showcased precise control, endurance, and innovative design. It marked a proud achievement for the Soaring Eagles Aeromodelling Team.', '/images/projects/abhyas-2024.png', 1005, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM projects WHERE title = 'Abhyas' AND project_year = 2024);
