INSERT INTO projects (id, title, project_year, description, image_url, position, published, created_at, updated_at) SELECT '57351db0-d0ef-5288-a7cd-b5522fe6bc04', 'Ornithopter', 2021, 'A bird-like flying machine that flaps its wings to generate lift and thrust. It was built in 2021 as part of an experimental aero-design project focused on biomimetic flight. The structure uses lightweight materials such as carbon fiber and thin polymer film for efficient flapping. Its motion is powered by a compact servo-motor mechanism controlled via remote or onboard electronics. The project demonstrates how nature-inspired flight dynamics can be applied in robotics and drone technology.', '/images/projects/ornithopter-2021.jpg', 1006, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM projects WHERE title = 'Ornithopter' AND project_year = 2021);
