INSERT INTO projects (id, title, project_year, description, image_url, position, published, created_at, updated_at) SELECT '8dbdd507-ea69-5859-91fb-3667d820ec7b', 'Hexacopter Drone', 2017, 'A six-rotor unmanned aerial vehicle designed for stable and powerful flight. It was built in 2017 as part of an engineering project focusing on multirotor control and payload capacity. The drone’s carbon-fiber frame and brushless DC motors provide durability and efficient lift. Its flight is managed by an onboard flight controller system integrated with GPS and IMU sensors. This project demonstrates advancements in aerial robotics and autonomous flight technology.', '/images/projects/hexacopter-2017.jpg', 1007, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM projects WHERE title = 'Hexacopter Drone' AND project_year = 2017);
INSERT INTO project_tags (project_id, position, tag) SELECT '8dbdd507-ea69-5859-91fb-3667d820ec7b', 0, 'Telemetry' WHERE EXISTS (SELECT 1 FROM projects WHERE id = '8dbdd507-ea69-5859-91fb-3667d820ec7b') AND NOT EXISTS (SELECT 1 FROM project_tags WHERE project_id = '8dbdd507-ea69-5859-91fb-3667d820ec7b' AND tag = 'Telemetry');
