INSERT INTO projects (id, title, project_year, description, image_url, position, published, created_at, updated_at) SELECT 'e8327b2f-22d8-55b8-bfe3-e26a30ad0229', 'Fixed-Wing RC Plane - Manove Gam', 2017, 'This image shows a fixed-wing RC aircraft developed during the Manove Gam workshop in 2017. It features a monoplane design with a lightweight fuselage and a front-mounted propeller for efficient thrust. The aircraft was built to study aerodynamic stability, lift generation, and control surface dynamics. Constructed using balsa wood and composite materials, it balances strength with minimal weight. This project marked an important step in hands-on aeromodelling and flight mechanics training for participants.', '/images/projects/manove-gam-2017.jpg', 1008, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM projects WHERE title = 'Fixed-Wing RC Plane - Manove Gam' AND project_year = 2017);
