INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT 'ca54c5a7-2433-5ddf-ba74-a076037e0c7c', 2025, 'SAEINDIA ADDC Workshop Phase 1 — SRM Chennai', 'At the Autonomous Drone Development Challenge workshop (SAEINDIA ISS), our team assembled, configured, and flew a drone from scratch. The workshop introduced practical work with Pixhawk flight controllers, autonomous mission planning, and UAV systems integration.', '/images/journey/2025ADDC.jpeg', 1000, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'SAEINDIA ADDC Workshop Phase 1 — SRM Chennai' AND milestone_year = 2025);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT 'f3b4a9f1-db66-56b7-a482-9e8e2609e60c', 2025, 'SAEINDIA DDC Workshop Phase 1 — NSS College of Engineering, Palakkad', 'At the Drone Development Challenge workshop organized by SAEINDIA Southern Section, our team designed, built, and flew a fixed-wing UAV, gaining hands-on experience in aerodynamics, electronics, and UAV applications.', '/images/journey/2025DDC.jpeg', 1001, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'SAEINDIA DDC Workshop Phase 1 — NSS College of Engineering, Palakkad' AND milestone_year = 2025);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT '3acda917-eb85-51ee-b913-c8d860df44d7', 2025, 'SAEINDIA Aerothon — GAT, Bengaluru', 'We submitted a UAV design report covering aerodynamics, mission planning, and subsystem integration. The team was appreciated for its design approach, structural analysis, and payload delivery strategy.', '/images/journey/2025Aerothon.jpg', 1002, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'SAEINDIA Aerothon — GAT, Bengaluru' AND milestone_year = 2025);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT '6a0bb2dd-6243-5996-8edb-3551e334540c', 2024, 'Boeing National Aero Modelling Competition — IIT Bombay', 'Two club teams designed and fabricated fixed-wing UAVs focused on payload capacity and precision delivery. The previous site reports 10th- and 15th-place finishes among more than 250 teams; these results should be confirmed before production.', '/images/journey/2024IITB.jpeg', 1003, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'Boeing National Aero Modelling Competition — IIT Bombay' AND milestone_year = 2024);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT '644bd40c-ed0a-5535-a96f-182c24e0b4ce', 2024, 'Wright Flight — NIT Surathkal', 'We designed and fabricated a fixed-wing UAV for aerobatic maneuvers and payload transport, then demonstrated its stability and maneuverability while completing the mission checkpoints.', '/images/journey/2024WrightFlight.jpeg', 1004, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'Wright Flight — NIT Surathkal' AND milestone_year = 2024);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT '379b3c78-15d0-515e-aa04-20f17b025282', 2023, 'SAEINDIA Aerothon — GAT, Bengaluru', 'The team took on an end-to-end uncrewed aircraft design, build, and piloting challenge. The previous site reports 11th place among more than 150 teams; confirm the result with the club before production.', '/images/journey/2023Aerothon.jpeg', 1005, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'SAEINDIA Aerothon — GAT, Bengaluru' AND milestone_year = 2023);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT 'd70c566f-db7a-560a-8012-c74cfd927678', 2020, 'SAE Aero Design — Texas, USA', 'We competed in SAE International’s student aerospace competition, designing and flight-testing a radio-controlled aircraft around payload efficiency, lift, and endurance. The previous site reports an international 23rd-place finish; confirm the result with the club before production.', '/images/journey/2020International.jpeg', 1006, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'SAE Aero Design — Texas, USA' AND milestone_year = 2020);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT '95541709-1da7-549b-a65b-42f7a71d5cb1', 2019, 'SAEISS Aero Design Challenge — SRM IST, Chennai', 'In the micro class, the team designed a fixed-wing UAV to lift payload within strict size and weight limits. The previous site reports 33rd place in a national competition of 144 teams; confirm the result with the club before production.', '/images/journey/2019ADDC.jpeg', 1007, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'SAEISS Aero Design Challenge — SRM IST, Chennai' AND milestone_year = 2019);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT '64bceee0-d540-5ea9-9a74-5a03b65715c5', 2019, 'Autonomous Drone Hackathon — IIT Kanpur', 'The team reached the finals of Techkriti’s International Multi-Rotor Challenge, working on autonomous flight, stability control, and mission-based aerial tasks.', '/images/journey/2019IITK.jpeg', 1008, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'Autonomous Drone Hackathon — IIT Kanpur' AND milestone_year = 2019);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT 'ce360b11-f6f2-5fb1-8e01-90c101c953f8', 2017, 'MANOVEGAM — Bengaluru', 'The team took part in the SAE International Student Section Aero Design Challenge, a student competition centered on designing and building lightweight unmanned aircraft.', '/images/journey/2017MANovegam.jpeg', 1009, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'MANOVEGAM — Bengaluru' AND milestone_year = 2017);
INSERT INTO journey_milestones (id, milestone_year, title, description, image_url, position, published, created_at, updated_at) SELECT '08282234-6efd-5578-9384-ed0fc1561ee7', 2017, 'SAE Aero Design West — Van Nuys, California', 'We participated in SAE International’s aircraft design competition, designing, building, and flight-testing a remote-controlled aircraft for payload capacity, aerodynamic efficiency, and flight stability. The previous site reports an international 12th-place finish; confirm the result with the club before production.', '/images/journey/2017International.jpeg', 1010, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM journey_milestones WHERE title = 'SAE Aero Design West — Van Nuys, California' AND milestone_year = 2017);
